screens=[]
def add(id,level,ru_title,en_title,ru,en,refs,section=('Чарли и Элджернон','Charlie and Algernon')):
 screens.append(dict(id=id,level=level,claimType='book',sources=refs,copy=pair(dict(section=section[0],title=ru_title,body='<p>'+ru+'</p>'),dict(section=section[1],title=en_title,body='<p>'+en+'</p>'))))
add('cover',1,'Цветы для Элджернона','Flowers for Algernon','Чарли Гордон хочет научиться тому, что другим даётся легко. В лаборатории ему предлагают операцию, которую уже испытали на белой мыши. Роман Дэниела Киза, 1966. Краткая история своими словами: Essential и Core останавливаются перед развязкой. Deep раскрывает открытия и исходы после предупреждения.','Charlie Gordon wants to learn what comes easily to other people. A laboratory offers him an operation already performed on a white mouse. Daniel Keyes’s 1966 novel, retold briefly in original words. Essential and Core stop before the resolution. Deep reveals the discoveries and outcomes after a warning.',[1,2],('Роман · 1966','Novel · 1966'))
screens[0]['type']='cover';screens[0]['copy']['ru']['subtitle']='Дэниел Киз';screens[0]['copy']['en']['subtitle']='Daniel Keyes'
add('evening-class',1,'После работы — к мисс Кинниан','After work, Miss Kinnian’s class','Чарли тридцать два года. Он убирает в пекарне Доннера и ходит учиться к Алисе Кинниан. Читать и писать трудно, но он возвращается на занятия: ему хочется стать умнее и обрести друзей. Алиса рекомендует его исследователям. Теперь Чарли должен записывать всё, что с ним происходит. Его первые отчёты полны ошибок.','Charlie is thirty-two. He cleans at Donner’s bakery and attends Alice Kinnian’s classes. Reading and writing are difficult, but he keeps coming back: he wants to become smarter and have friends. Alice recommends him to researchers. Now Charlie must write down everything that happens to him. His first reports are full of mistakes.',[4,16,20])
add('inkblots',2,'Что спрятано в пятнах?','What is hidden in the blots?','Перед операцией Чарли проходит обследования. Ему показывают чернильные пятна и предлагают сказать, что он видит. Он старается найти правильный ответ и боится не справиться. Исследователи узнают о его возможностях; Чарли же тревожится, возьмут ли его в опыт. Он не хочет упустить шанс научиться.','Before the operation, Charlie takes tests. He is shown inkblots and asked what he sees. He tries to find the right answer and fears getting it wrong. The researchers are learning about his abilities; Charlie worries about whether they will let him into the experiment. He does not want to lose his chance to learn.',[4,20])
add('white-mouse',1,'Мышь приходит первой','The mouse finishes first','В лаборатории Чарли знакомится с Элджерноном. Белая мышь проходит свой лабиринт быстрее, чем Чарли решает предложенную ему задачу. Элджернону уже сделали операцию, которая повысила его способности. Теперь похожую процедуру хотят впервые испытать на человеке. Чарли обидно проигрывать мыши, но её успех даёт ему надежду.','At the laboratory Charlie meets Algernon. The white mouse finishes his maze faster than Charlie can solve the task set for him. Algernon has already had an operation that increased his abilities. A similar procedure is now to be tried on a human for the first time. Losing to a mouse hurts Charlie, but Algernon’s success gives him hope.',[1,4,6,20])
add('chosen-subject',2,'Кого возьмут в опыт','Choosing the subject','Профессор Немур сомневается, подходит ли Чарли. Доктор Штраус защищает его кандидатуру: желание учиться необыкновенно сильное. Чарли предупреждают, что успех не гарантирован. Немур говорит о вкладе в науку и известности; Чарли важнее, чтобы люди его любили. Он соглашается, представляя, как изменится его жизнь.','Professor Nemur doubts whether Charlie is suitable. Dr. Strauss argues for him: his desire to learn is unusually strong. Charlie is warned that success is not guaranteed. Nemur talks about science and fame; Charlie cares more about being liked. He agrees, imagining how his life will change.',[4,16,20])
add('after-bandages',1,'Повязки сняли. Что изменилось?','The bandages are off. What has changed?','Операция позади, а Чарли всё ещё не понимает того, чего не понимал раньше. Он ждал, что станет умным сразу. Алиса объясняет: нужно время. Он возвращается к отчётам, занятиям и проверкам. Скоро перемены начинают появляться и в том, как он решает задачи, и в том, как пишет о себе.','The operation is over, but Charlie still cannot understand things he could not understand before. He expected to become smart at once. Alice explains that it will take time. He returns to reports, lessons and tests. Soon changes begin to appear both in how he solves problems and in how he writes about himself.',[5,6])
add('winning-race',1,'Теперь Чарли обгоняет Элджернона','Now Charlie beats Algernon','Наконец Чарли побеждает Элджернона в состязании. Однако он замечает и другое: мышь должна решить задачу, чтобы получить еду. Чарли это не нравится. Он уже не просто соперничает с Элджерноном — он хочет с ним дружить. Рядом с этим маленьким участником опыта ему всё чаще приходится думать и о собственном положении.','At last Charlie beats Algernon in a race. But he notices something else: the mouse has to solve a problem to get food. Charlie dislikes that arrangement. Algernon is becoming more than a rival; Charlie wants to be his friend. Beside this small fellow subject, he increasingly has to think about his own position too.',[6])
add('laughter-changes',1,'Те же люди, другой смех','The same people, a different laugh','В пекарне Чарли привык смеяться вместе с Джо Карпом и Фрэнком Рейли. Теперь он начинает понимать, над кем они смеялись. Он вспоминает, как приятели напоили его и бросили одного. Когда-то он принимал такие выходки за дружбу. Новая способность понимать людей приносит стыд и злость: изменить смысл старых воспоминаний уже нельзя.','At the bakery Charlie used to laugh along with Joe Carp and Frank Reilly. Now he begins to understand whom they were laughing at. He remembers his companions getting him drunk and leaving him alone. Once he took such pranks for friendship. Understanding other people now brings shame and anger: the old memories can no longer mean what they did.',[6,7])
add('gimpys-choice',2,'Выдать Гимпи?','Should he report Gimpy?','Чарли обнаруживает, что Гимпи обкрадывает Доннера. Прежде Гимпи мог рассчитывать, что Чарли ничего не заметит. Но Гимпи помогал ему в пекарне, а Доннер дал ему работу. Чарли ищет совета и в конце концов говорит с Гимпи сам: если тот прекратит воровать, он не станет сообщать хозяину. Гимпи соглашается неохотно.','Charlie discovers that Gimpy is stealing from Donner. Gimpy could once count on Charlie not noticing. Yet Gimpy has helped him at the bakery, and Donner gave him a job. Charlie seeks advice and eventually confronts Gimpy himself: if the stealing stops, he will not tell the owner. Gimpy agrees reluctantly.',[8,21])
add('bakery-dismissal',1,'Пекарня больше не ждёт его','The bakery no longer wants him','Чарли осваивает более сложную работу, но коллег пугают его быстрые перемены. Они требуют, чтобы он ушёл. Доннер увольняет его. Пекарня была местом, где его знали много лет, почти семьёй. Теперь, когда Чарли способен на большее, ему приходится покинуть её.','Charlie masters more demanding work, but his rapid changes frighten his coworkers. They press for his removal. Donner dismisses him. The bakery was where people had known him for years, almost a family. Now that Charlie can do more, he has to leave it.',[7,8,21])
add('alice-close',1,'Сказать ей «Алиса»','Calling her Alice','Мисс Кинниан становится для Чарли Алисой. Они встречаются вне занятий, и он влюбляется в неё. Но попытка приблизиться вызывает панику. Вместе с новыми знаниями возвращаются детские воспоминания, от которых прежде оставалось лишь смутное чувство страха. С Алисой он хочет быть рядом, а ведёт себя так, будто кто-то за ним наблюдает.','Miss Kinnian becomes Alice to Charlie. They meet outside class, and he falls in love with her. But trying to get closer brings panic. Alongside new knowledge come childhood memories that once left only a vague fear. He wants to be with Alice, yet acts as though someone is watching him.',[8,21])
add('childhood-rooms',2,'Воспоминания о доме','Memories of home','Он вспоминает мать, Розу, которая пыталась заставить его стать таким, как другие дети, и жестоко наказывала за проявления интереса к девочкам. Отец, Мэтт, пытался его защищать. С появлением младшей сестры Нормы семейные ссоры только усилились. Взрослый Чарли начинает различать в собственном страхе голоса и угрозы из того дома.','He remembers his mother, Rose, trying to make him like other children and harshly punishing his interest in girls. His father, Matt, tried to protect him. After the birth of his younger sister Norma, the family’s conflicts grew worse. The adult Charlie begins to recognize voices and threats from that house within his own fear.',[8,9,10])
add('outpacing-teachers',2,'Разговоры становятся тесными','Outgrowing the conversations','Сначала беседы со студентами кажутся Чарли входом в огромный новый мир. Потом их знаний ему уже не хватает. Он обгоняет и людей, которых считал непререкаемыми авторитетами. Алисе больно от его снисходительности. Чарли хотел понимать окружающих, но всё чаще раздражается и отдаляется от них.','At first, conversations with students seem to open an enormous new world. Then their knowledge no longer satisfies him. He surpasses people he once regarded as unquestionable authorities. His condescension hurts Alice. Charlie wanted to understand the people around him, but increasingly becomes impatient and withdraws from them.',[7,8])
add('chicago-presentation',1,'На сцене в Чикаго','Onstage in Chicago','Немур и Штраус везут Чарли и Элджернона на научную конференцию. Исследователи спорили, не рано ли объявлять успех. Теперь Чарли слушает доклады о самом себе. Немур говорит так, словно до операции у Чарли не было человеческой жизни. Чарли возмущён — и уже способен понять, почему уверенность учёных в долговечности результата недостаточно обоснована.','Nemur and Strauss take Charlie and Algernon to a scientific convention. The researchers have disagreed about whether it is too soon to announce success. Now Charlie listens to papers about himself. Nemur speaks as though Charlie had no human life before the operation. Charlie is furious—and can now understand why the scientists’ confidence in a lasting result is inadequately supported.',[7,9,21,22])
add('burts-objection',2,'Берт спорит с Чарли','Burt argues back','Чарли видит ограниченность знаний Немура и Штрауса и обвиняет их в несостоятельности. Берт защищает исследователей: это обыкновенные люди, пытающиеся выполнить необыкновенную работу. Он упрекает и самого Чарли, чья образованность выросла быстрее, чем способность обходиться с людьми. Чарли не принимает роли экспоната, но его собственное обращение с другими тоже становится причиной ссор.','Seeing the limits of Nemur’s and Strauss’s knowledge, Charlie attacks their competence. Burt defends them as ordinary people attempting extraordinary work. He also challenges Charlie, whose education has grown faster than his ability to deal with others. Charlie refuses to be an exhibit, but his own treatment of people is also provoking quarrels.',[9])
add('two-escapees',1,'Двое покидают конференцию','Two escape the convention','Чарли выпускает Элджернона из клетки, вызывает переполох и уезжает с ним в Нью-Йорк. Он больше не хочет оставаться послушным доказательством чужого успеха. В новой квартире поселяются человек и мышь, прошедшие похожую операцию. Чарли строит для Элджернона лабиринт, по которому тот может бегать не только ради еды.','Charlie releases Algernon from his cage, creates an uproar and takes him back to New York. He no longer wants to remain obedient proof of someone else’s success. A man and a mouse who have undergone similar operations settle into a new apartment. Charlie builds Algernon a maze he can explore without having to earn food.',[9,10])
add('fathers-barbershop',2,'В кресле у отца','In his father’s barber chair','Газетная история об опыте помогает Чарли найти отца. Он приходит в его парикмахерскую, но Мэтт не узнаёт сына. Чарли так и не решается назвать себя. Он боится, что отец отвергнет изменившегося человека; это страх Чарли, а не ответ, который Мэтт успел дать. Встреча заканчивается без признания.','A newspaper story about the experiment helps Charlie find his father. He visits Matt’s barbershop, but Matt does not recognize his son. Charlie cannot bring himself to reveal his identity. He fears his father would reject the changed man; that is Charlie’s fear, not an answer Matt has given. The visit ends without recognition.',[10,17])
add('fay-next-door',2,'Соседка Фэй','Fay next door','Соседка, художница Фэй Лиллман, входит в его новую жизнь с танцами, выпивкой и близостью. С ней Чарли удаётся то, что пока не получается с Алисой. Но отношения с Фэй не избавляют его от одиночества и страха перед прежним собой. Элджернон живёт рядом — теперь уже не за стенами лаборатории.','His neighbor, the painter Fay Lillman, brings dancing, drinking and intimacy into his new life. With her, Charlie manages what he has not yet managed with Alice. But being with Fay does not end his loneliness or his fear of his former self. Algernon is beside him, now outside the laboratory walls.',[10])
add('broken-plates',1,'Смех в закусочной','Laughter in the diner','В закусочной молодой работник с интеллектуальными нарушениями роняет посуду. Посетители смеются, и Чарли сперва смеётся вместе с ними. Потом понимает, что сам когда-то стоял на месте этого юноши. Он останавливает насмешки. После этой встречи Чарли решает вернуться к исследованию опыта: ему хочется сделать что-то и для других людей.','In a diner, a young worker with an intellectual disability drops dishes. The customers laugh, and at first Charlie laughs along. Then he realizes he once stood where the young man stands. He stops the mockery. After this encounter Charlie decides to return to researching the experiment: he wants to do something for other people too.',[10])
add('unfamiliar-maze',1,'Элджернон ведёт себя иначе','Algernon behaves differently','Элджернон становится беспокойным и непредсказуемым. Задачи, с которыми он справлялся, начинают даваться ему хуже. Чарли видит перемены у того, кто прошёл опыт раньше него. Уверенности, что операция даёт постоянный результат, больше нет. Теперь ему нужно понять, что происходит с Элджерноном и что это может означать для него самого.','Algernon becomes restless and unpredictable. Tasks he once mastered grow harder for him. Charlie sees the changes in the creature who underwent the experiment before him. He can no longer be sure the operation produces a lasting result. Now he must understand what is happening to Algernon and what it may mean for himself.',[10,11])
add('researcher-returns',1,'Вернуться на своих условиях','Returning on his own terms','Чарли получает поддержку фонда для собственного исследования и возвращается в лабораторию с Элджерноном. На этот раз он хочет разбирать данные сам. Люди, прежде проверявшие его, должны помогать ему в работе. Перед ним ещё открытые вопросы: почему меняется поведение мыши, что было упущено в расчётах и сколько времени есть на поиск ответа.','Charlie obtains foundation support for his own research and returns to the laboratory with Algernon. This time he wants to examine the data himself. People who once tested him must help him work. The questions remain open: why the mouse is changing, what the calculations missed, and how much time there is to find an answer.',[11])
add('warren-visit',3,'Место, приготовленное заранее','A place already arranged','От Берта Чарли узнаёт: если он утратит новые способности, предусмотрено место в учреждении Уоррена. Он просит показать ему это место, пока может понять, что видит. Персонал старается заботиться о жителях, но Чарли страшно представить себя среди них. Ещё он просит не уничтожать Элджернона вместе с другими умершими лабораторными животными: о мыши он позаботится сам.','Burt tells Charlie that a place at the Warren Home has been arranged if he loses his new abilities. He asks to visit while he can still understand what he sees. The staff try to care for the residents, but imagining himself among them frightens him. He also asks that Algernon not be disposed of with other dead laboratory animals: he will take care of the mouse himself.',[11,12,14])
add('nemurs-party',3,'После приёма','After the party','На приёме Чарли снова ссорится с Немуром. Для учёных даже неудачный опыт может дать важные знания; Чарли приходится жить внутри этого опыта. Он отвергает притязание Немура на то, будто тот создал его как человека. Немур отвечает, что Чарли стал высокомерным и эгоистичным. Уйдя, Чарли не может просто отмахнуться от этого упрёка.','At a party Charlie quarrels with Nemur again. Even a failed experiment may give the scientists valuable knowledge; Charlie has to live inside that experiment. He rejects Nemur’s claim to have created him as a person. Nemur replies that Charlie has become arrogant and self-centered. After leaving, Charlie cannot simply dismiss the accusation.',[12,14])
add('nights-at-lab',3,'Ночи в лаборатории','Nights at the laboratory','Чарли всё глубже уходит в работу и часто остаётся ночевать в лаборатории. Фэй находит другого мужчину, а Чарли уже почти не отвлекается от исследования. Элджернон может уверенно начать путь по лабиринту, а затем растеряться. Чтобы объяснить эти перемены, Чарли работает с той настойчивостью, с какой прежде стремился в сам опыт.','Charlie immerses himself in work, often sleeping at the laboratory. Fay finds another man, while Charlie scarcely looks away from his research. Algernon may begin a maze confidently, then become lost. To explain these changes, Charlie works with the persistence he once brought to getting into the experiment itself.',[12,14])
add('algernon-gordon-effect',3,'Работа с двумя именами','A paper with two names','Он находит ошибку в предположении о постоянстве результата. В работе об эффекте Элджернона — Гордона Чарли описывает установленную им в рамках опыта связь: чем больше искусственный прирост интеллекта, тем быстрее последующее угасание. Значит, открытие касается и его. Он отправляет выводы Немuru и Штраусу. Ответ получен, но способа сохранить новые способности у него нет.','He finds the flaw in the assumption that the result will last. In his paper on the Algernon-Gordon Effect, Charlie describes the relationship he has established within the experiment: the greater the artificial increase in intelligence, the faster the subsequent deterioration. The discovery applies to him too. He sends his findings to Nemur and Strauss. He has an answer, but no way to preserve his new abilities.',[12,14,18])
add('algernon-buried',3,'Чарли хоронит Элджернона','Charlie buries Algernon','Элджернон умирает. Чарли исследует его тело, а затем хоронит во дворе и кладёт на могилу цветы. В лаборатории остаются результаты наблюдений; во дворе — тот, с кем Чарли соревновался, подружился и сбежал из Чикаго. У самого Чарли уже появляются провалы памяти. Но прежде чем станет поздно, он хочет увидеть мать.','Algernon dies. Charlie examines his body, then buries him in the backyard and puts flowers on the grave. The laboratory keeps the observations; the yard holds the companion he raced, befriended and took away from Chicago. Charlie himself is beginning to have lapses of memory. Before it is too late, he wants to see his mother.',[12,14,18])
add('rose-and-norma',3,'Мать, сестра и нож','His mother, his sister and a knife','Роза уже не всегда понимает, кто перед ней. Чарли показывает ей свою научную работу: теперь он может учиться, теперь она может им гордиться. Норма радуется возвращению брата и просит прощения за детскую жестокость. Но внезапно Роза хватает нож и требует, чтобы Чарли не приближался к сестре. Он уходит в слезах. Встреча с Нормой состоялась; вернуть прежний дом она не смогла.','Rose no longer always understands who is before her. Charlie shows her his paper: now he can learn, now she can be proud of him. Norma is delighted to see her brother and apologizes for her childhood cruelty. But Rose suddenly seizes a knife and orders Charlie away from his sister. He leaves in tears. He has reached Norma; the reunion has not restored his old home.',[12,14])
add('books-close',3,'Книга, которую он понимал','A book he once understood','Чарли снова не справляется с лабораторными тестами и отказывается приходить. Он открывает «Потерянный рай» — книгу, которой недавно восхищался, — но больше не понимает её. В ярости он рвёт том. Каждая такая попытка напоминает ему о том, что ещё недавно было доступно. Он продолжает записывать происходящее, пока может.','Charlie struggles with the laboratory tests again and refuses to return. He opens Paradise Lost, a book he recently admired, but can no longer understand it. Furious, he tears it apart. Each attempt reminds him of something that was within his reach so recently. He keeps recording what happens while he can.',[13,15])
add('alice-stays',3,'Алиса остаётся','Alice stays','Алиса приходит жить к нему. На этот раз прежняя паника отступает: они наконец могут быть близки. Чарли хочет провести с ней оставшееся время, но ему тяжело думать о том, что ей предстоит видеть. Он заранее просит её уйти, когда он скажет, и обещать, что после этого она не вернётся. Пока они вместе.','Alice comes to stay with him. This time the old panic recedes, and they can finally be intimate. Charlie wants the remaining time with her, but struggles to think of what she will have to witness. He asks her in advance to leave when he tells her to, and to promise she will not return afterward. For now, they are together.',[13,15])
add('unreadable-paper',3,'Собственная работа становится чужой','His own paper becomes unreadable','Скоро Чарли не может понять и свою работу об эффекте Элджернона — Гордона. Попытки Алисы помочь и побудить его заниматься вызывают раздражение. Он вспоминает давление матери и требует, чтобы Алиса ушла. Она выполняет обещание. Чарли продолжает пробовать учиться, но утраты не прекращаются. В отчётах возвращаются ошибки. Он не хочет жить на деньги Алисы и Штрауса и решает искать работу.','Soon Charlie cannot understand his own paper on the Algernon-Gordon Effect. Alice’s attempts to help and encourage him to study make him angry. He remembers his mother’s pressure and orders Alice to leave. She keeps her promise. Charlie continues trying to learn, but the losses persist. Mistakes return to his reports. He does not want to live on money from Alice and Strauss and decides to seek work.',[13,15])
add('bakery-again',3,'Снова у Доннера','Back at Donner’s','Доннер берёт его обратно. Новый работник, Мейер Клаус, начинает издеваться над Чарли и угрожает ему. На этот раз Джо, Фрэнк и Гимпи вступаются за него. Чарли рад, что у него снова есть друзья. Это те самые люди, чьи насмешки он когда-то принимал за дружбу, а потом научился понимать.','Donner takes him back. A new employee, Meyer Klaus, bullies and threatens Charlie. This time Joe, Frank and Gimpy defend him. Charlie is glad to have friends again. These are the same people whose mockery he once mistook for friendship and later learned to understand.',[13,15])
add('old-classroom',3,'Мисс Кинниан выбегает из класса','Miss Kinnian leaves the classroom','Забыв, что больше не учится у мисс Кинниан, Чарли приходит на занятие. Увидев его, Алиса выбегает в слезах. Он замечает, что знакомые его жалеют, и решает уехать в Уоррен. О том, как сложится жизнь там, его записи не рассказывают. Чарли прощается с людьми, которых знал.','Forgetting that he no longer attends Miss Kinnian’s class, Charlie turns up for a lesson. Alice sees him and runs out in tears. He senses that the people he knows feel sorry for him and decides to go to Warren. His reports do not tell what life there will be like. Charlie says goodbye to the people he has known.',[13,15])
add('last-request',3,'Просьба о цветах','A request for flowers','В последних записях Чарли трудно выразить всё, что он помнит. Он рад, что какое-то время был умным и узнал о своей семье. Напоследок он просит тех, кто останется, приносить цветы на могилу Элджернона во дворе. На этой просьбе его отчёты обрываются.','In the last entries Charlie struggles to express what he remembers. He is glad he was smart for a time and learned about his family. Finally he asks those who remain to put flowers on Algernon’s grave in the backyard. His reports end with that request.',[13,15])
add('final',1,'Конец выбранного маршрута','End of this reading path','Essential и Core останавливаются перед последней частью истории. Чтобы прочитать её завершение, выберите Deep и подтвердите предупреждение о спойлерах. Полный роман Киза сохраняет голос отчётов и подробности, которые короткий пересказ не воспроизводит.','Essential and Core stop before the last part of the story. To read its conclusion, choose Deep and confirm the spoiler warning. Keyes’s complete novel retains the reports’ voice and details that this short retelling does not reproduce.',[],('Чтение','Reading'))
screens[-1]['final']=True;screens[-1]['claimType']='synthesis'
